"use strict";
/* ============ Verace Studio — editor ibrido ============ */
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const uid=()=>Math.random().toString(36).slice(2,9);
const fmt=t=>{t=Math.max(0,t||0);const m=Math.floor(t/60),s=Math.floor(t%60),d=Math.floor((t*10)%10);return m+":"+String(s).padStart(2,"0")+"."+d;};
const esc=s=>String(s==null?"":s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove("show"),2200);}
function fmtDate(ms){try{return new Date(ms).toLocaleDateString("it-IT",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"});}catch(e){return"";}}
const LS={get(k,d){try{const v=localStorage.getItem(k);return v==null?d:JSON.parse(v);}catch(e){return d}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}};
const PALETTE=["#FBF4E6","#2B2724","#C7A45E","#A8636A","#AC3F3F","#3E7A54","#E0C488","#F3E9D6"];
const FONTS=[["Outfit","Outfit"],["Fraunces","Fraunces"],["Caveat","Caveat"]];
const PRESETS={none:"Naturale",bw:"B/N",warm:"Caldo",cold:"Freddo",vivid:"Vivido",soft:"Soft"};
const SUBSTYLES={classico:{name:"Classico",font:"Outfit",color:"#FBF4E6",bold:true,box:null,size:28},box:{name:"Box scuro",font:"Outfit",color:"#FFFFFF",bold:true,box:"#2B2724",size:26},karaoke:{name:"Karaoke",font:"Outfit",color:"#E0C488",bold:true,box:null,size:34},pop:{name:"Pop rosso",font:"Outfit",color:"#FFFFFF",bold:true,box:"#AC3F3F",size:27},minimal:{name:"Minimal",font:"Outfit",color:"#FBF4E6",bold:false,box:null,size:24},elegante:{name:"Elegante",font:"Fraunces",color:"#F3E9D6",bold:false,box:null,size:30}};
const EMOJIS=["🎄","🎅","⛄","🦌","🎁","✨","❄️","🔔","⭐","😍","🔥","👇","💥","🤍","🧡","🎬"];

const S={src:null,segments:[],audios:[],overlays:[],playhead:0,playing:false,sel:null,pps:48,undo:[],
  projectId:null,projectName:"",projectCreatedAt:null,vibe:null,textStyle:{font:"Outfit",color:"#FBF4E6",bold:true},
  refThumb:null,refBlob:null,chat:[],_greeted:false,renderKaraoke:false,
  audioFx:{voice:false,noise:false},videoFx:{enhance:false},brand:{colors:[],font:null,logos:[]},chatAtt:null};
let AC=null,master=null,exportDest=null,vidSrcNode=null,vidGain=null,playingSources=[],vHP=null,vEQ=null,vComp=null;
let DL=null;const CAP={db:null,assets:null,user:null,sample:null,tts:null,ready:false,canWrite:true,sampleImages:false};
let activeTab="vibe",relinkTarget=null,subStyle="classico",exportRes=[1440,2560],capMode="frasi";
const imgCache={};
const canvas=$("#canvas"),ctx=canvas.getContext("2d");let CW=canvas.width,CH=canvas.height;
const stage=$("#stage"),tlinner=$("#tlinner"),ruler=$("#ruler"),playheadEl=$("#playheadEl");

/* ---- caps ---- */
async function initCaps(){
  if(window.claude&&claude.use){try{
    const [db,assets,user,dl,sample,tts]=await Promise.all([
      claude.use("db").catch(()=>null),claude.use("assets").catch(()=>null),claude.use("user").catch(()=>null),
      claude.use("downloads").catch(()=>null),claude.use("sample").catch(()=>null),claude.use("tts").catch(()=>null)]);
    CAP.db=db;CAP.assets=assets;CAP.user=user;DL=dl;CAP.sample=sample;CAP.tts=tts;CAP.ready=true;
    if(user){try{const w=await user.can("data.write");CAP.canWrite=(w!==false);}catch(e){}}
    if(sample){try{const lim=await sample.limits();CAP.sampleImages=!!(lim&&lim.images);}catch(e){}}
  }catch(e){}}
  updateStudioUI();await brandLoad();if(activeTab==="chat")ensureChat();
}
const cloudOn=()=>!!(CAP.db&&CAP.assets);

/* ---- mapping ---- */
const segDur=s=>s.out-s.in;
const total=()=>S.segments.reduce((a,s)=>a+segDur(s),0);
function segStart(i){let a=0;for(let k=0;k<i;k++)a+=segDur(S.segments[k]);return a;}
function locate(t){let a=0;for(let i=0;i<S.segments.length;i++){const d=segDur(S.segments[i]);if(t<a+d||i===S.segments.length-1)return{i,src:S.segments[i].in+clamp(t-a,0,d)};a+=d;}return null;}
function newSeg(i,o){return{id:uid(),in:i,out:o,eff:{bri:100,con:100,sat:100,scale:100,preset:"none"},fx:{},fi:0,fo:0};}

/* ---- undo ---- */
function snapshot(){try{S.undo.push(JSON.stringify({segments:S.segments,overlays:S.overlays.map(o=>({...o,_img:undefined})),vibe:S.vibe,textStyle:S.textStyle,
  audios:S.audios.map(a=>({id:a.id,name:a.name,sfx:a.sfx,start:a.start,in:a.in,out:a.out,vol:a.vol,missing:a.missing}))}));
  if(S.undo.length>40)S.undo.shift();$("#undoBtn").disabled=false;}catch(e){}}
function undo(){if(!S.undo.length)return;const st=JSON.parse(S.undo.pop());S.segments=st.segments;S.overlays=st.overlays;S.vibe=st.vibe;S.textStyle=st.textStyle;
  const map={};S.audios.forEach(a=>map[a.id]=a.buf);S.audios=st.audios.map(a=>({...a,buf:map[a.id]||null})).filter(a=>a.buf||a.sfx||a.missing);
  S.sel=null;$("#undoBtn").disabled=!S.undo.length;renderAll();drawFrame();}

/* ---- audio graph ---- */
function ensureAudio(){if(AC)return;AC=new (window.AudioContext||window.webkitAudioContext)();master=AC.createGain();master.gain.value=1;master.connect(AC.destination);exportDest=AC.createMediaStreamDestination();master.connect(exportDest);buildVideoChain();}
function buildVideoChain(){if(!S.src||vidSrcNode||!AC)return;try{vidSrcNode=AC.createMediaElementSource(S.src.el);
  vHP=AC.createBiquadFilter();vHP.type="highpass";vHP.frequency.value=20;
  vEQ=AC.createBiquadFilter();vEQ.type="peaking";vEQ.frequency.value=3000;vEQ.Q.value=1;vEQ.gain.value=0;
  vComp=AC.createDynamicsCompressor();vComp.threshold.value=0;vComp.ratio.value=1;vComp.attack.value=.003;vComp.release.value=.25;
  vidGain=AC.createGain();vidGain.gain.value=1;
  vidSrcNode.connect(vHP);vHP.connect(vEQ);vEQ.connect(vComp);vComp.connect(vidGain);vidGain.connect(master);setAudioFx();}catch(e){}}
function setAudioFx(){if(!AC||!vHP)return;vHP.frequency.value=S.audioFx.noise?130:20;vEQ.gain.value=S.audioFx.voice?5:0;vComp.threshold.value=S.audioFx.voice?-26:0;vComp.ratio.value=S.audioFx.voice?3:1;vidGain.gain.value=S.audioFx.voice?1.3:1;}

/* ---- load video ---- */
function loadVideoFromUrl(url,label,opts){opts=opts||{};const v=document.createElement("video");v.src=url;v.playsInline=true;v.preload="auto";v.crossOrigin="anonymous";
  v.addEventListener("loadedmetadata",()=>{S.src={el:v,url,dur:v.duration,w:v.videoWidth,h:v.videoHeight,blob:opts.blob||null,assetId:opts.assetId||null};
    if(opts.after){try{opts.after();}catch(e){}}else if(!S.segments.length)S.segments=[newSeg(0,v.duration)];
    stage.classList.remove("empty");canvas.classList.remove("hidden");$("#drop").classList.add("hidden");
    if(AC&&!vidSrcNode)buildVideoChain();
    S.playhead=0;seekTo(0);renderAll();S.sel=null;renderPanel();if(label)toast(label);
    if(opts.sfxRestore)opts.sfxRestore();
    if(opts.autoAfter){autoEdit();}else if(!opts.silentGreet)greet();},{once:true});
  v.addEventListener("seeked",()=>{if(!S.playing)drawFrame();});v.load();}
function resetForNew(){S.segments=[];S.audios=[];S.overlays=[];S.undo=[];S.projectId=null;S.vibe=null;S._greeted=false;$("#undoBtn").disabled=true;}
$("#videoFile").addEventListener("change",e=>{const f=e.target.files[0];if(!f)return;resetForNew();loadVideoFromUrl(URL.createObjectURL(f),"Video caricato",{blob:f,autoAfter:true});});
["dragover","drop"].forEach(ev=>stage.addEventListener(ev,e=>{e.preventDefault();if(ev==="drop"&&e.dataTransfer.files[0]){const f=e.dataTransfer.files[0];if(f.type.startsWith("video")){resetForNew();loadVideoFromUrl(URL.createObjectURL(f),"Video caricato",{blob:f,autoAfter:true});}}}));

/* ---- audio upload + relink ---- */
$("#audioFile").addEventListener("change",async e=>{const f=e.target.files[0];if(!f)return;ensureAudio();
  if(relinkTarget){const clip=S.audios.find(a=>a.id===relinkTarget);relinkTarget=null;if(clip){try{const buf=await AC.decodeAudioData(await f.arrayBuffer());clip.buf=buf;clip.blob=f;clip.missing=false;clip.out=Math.min(clip.out||buf.duration,clip.in+buf.duration);renderTracks();renderPanel();toast("Audio ricollegato");}catch(err){toast("Audio non supportato");}}e.target.value="";return;}
  try{const buf=await AC.decodeAudioData(await f.arrayBuffer());snapshot();S.audios.push({id:uid(),name:f.name.replace(/\.[^.]+$/,"").slice(0,22),buf,blob:f,sfx:null,assetId:null,start:S.playhead,in:0,out:buf.duration,vol:1,missing:false});renderTracks();select({kind:"audio",id:S.audios[S.audios.length-1].id});setTab("audio");toast("Suono aggiunto");}catch(err){toast("Audio non supportato");}e.target.value="";});

/* ---- filter ---- */
function filterFor(eff){let f=`brightness(${eff.bri}%) contrast(${eff.con}%) saturate(${eff.sat}%)`;if(eff.preset==="bw")f+=" grayscale(1)";else if(eff.preset==="warm")f+=" sepia(.35) saturate(135%) hue-rotate(-8deg)";else if(eff.preset==="cold")f+=" saturate(115%) hue-rotate(10deg) brightness(102%)";else if(eff.preset==="vivid")f+=" saturate(160%) contrast(108%)";else if(eff.preset==="soft")f+=" brightness(104%) contrast(94%) saturate(96%)";if(S.videoFx.enhance)f+=" contrast(108%) saturate(110%) brightness(102%)";return f;}
function alphaAt(t,i){const seg=S.segments[i];let a=1;const st=segStart(i),d=segDur(seg);if(seg.fi>0)a=Math.min(a,clamp((t-st)/seg.fi,0,1));if(seg.fo>0)a=Math.min(a,clamp((st+d-t)/seg.fo,0,1));return a;}

/* ---- FX ---- */
let noiseTile=null;function getNoise(){if(noiseTile)return noiseTile;const n=document.createElement("canvas");n.width=160;n.height=284;const g=n.getContext("2d"),d=g.createImageData(n.width,n.height);for(let i=0;i<d.data.length;i+=4){const v=Math.random()*255;d.data[i]=d.data[i+1]=d.data[i+2]=v;d.data[i+3]=255;}g.putImageData(d,0,0);noiseTile=n;return n;}
function drawFx(fx,t,lt){if(fx.leak){ctx.save();ctx.globalCompositeOperation="screen";const cx=CW*(0.5+0.4*Math.sin(t*0.6)),cy=CH*(0.3+0.1*Math.cos(t*0.5));const g=ctx.createRadialGradient(cx,cy,0,cx,cy,CW*0.95);g.addColorStop(0,"rgba(224,196,136,.5)");g.addColorStop(.5,"rgba(172,63,63,.16)");g.addColorStop(1,"rgba(0,0,0,0)");ctx.fillStyle=g;ctx.fillRect(0,0,CW,CH);ctx.restore();}
  if(fx.grain){ctx.save();ctx.globalAlpha=0.07;ctx.globalCompositeOperation="overlay";ctx.drawImage(getNoise(),-(Math.random()*30),-(Math.random()*30),CW+30,CH+30);ctx.restore();}
  if(fx.snow){ctx.save();ctx.fillStyle="#fff";for(let i=0;i<46;i++){const sp=18+(i%7)*6,y=((t*sp+i*53)%(CH+30))-15,x=(i*71%CW)+Math.sin(t*0.8+i)*16,r=1+(i%3)*0.9;ctx.globalAlpha=.35+(i%5)/9;ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fill();}ctx.restore();}
  if(fx.vignette){ctx.save();const g=ctx.createRadialGradient(CW/2,CH/2,CH*0.3,CW/2,CH/2,CH*0.63);g.addColorStop(0,"rgba(0,0,0,0)");g.addColorStop(1,"rgba(0,0,0,.5)");ctx.fillStyle=g;ctx.fillRect(0,0,CW,CH);ctx.restore();}
  if(fx.flash){const fl=Math.exp(-lt*7);if(fl>0.02){ctx.save();ctx.globalAlpha=Math.min(0.85,fl);ctx.fillStyle="#fff";ctx.fillRect(0,0,CW,CH);ctx.restore();}}}
function getImg(o){if(o._img)return o._img;const key=o.src;if(imgCache[key]){o._img=imgCache[key];return o._img;}const im=new Image();im.onload=()=>{if(!S.playing)drawFrame();};im.src=o.src;imgCache[key]=im;o._img=im;return im;}

/* ---- draw ---- */
function drawFrame(){CW=canvas.width;CH=canvas.height;ctx.clearRect(0,0,CW,CH);ctx.fillStyle="#141010";ctx.fillRect(0,0,CW,CH);
  const t=S.playhead,loc=S.src&&S.segments.length?locate(t):null;
  if(loc&&S.src){const seg=S.segments[loc.i],v=S.src.el,lt=t-segStart(loc.i),a=alphaAt(t,loc.i);let scale=Math.max(CW/S.src.w,CH/S.src.h)*(seg.eff.scale/100);if(seg.fx.zoom)scale*=1+0.14*Math.exp(-lt*5);let ox=0,oy=0;if(seg.fx.shake){ox=Math.sin(t*33)*CW*0.012;oy=Math.cos(t*39)*CH*0.012;}
    ctx.save();ctx.globalAlpha=a;ctx.filter=filterFor(seg.eff);const dw=S.src.w*scale,dh=S.src.h*scale;ctx.drawImage(v,(CW-dw)/2+ox,(CH-dh)/2+oy,dw,dh);ctx.restore();ctx.filter="none";ctx.globalAlpha=1;drawFx(seg.fx,t,lt);}
  for(const o of S.overlays){if(t<o.start||t>o.end)continue;
    if(o.kind==="image"){const im=getImg(o);if(im&&im.complete&&im.naturalWidth){const w=o.size/100*CW,h=w*im.naturalHeight/im.naturalWidth;ctx.save();ctx.shadowColor="rgba(0,0,0,.3)";ctx.shadowBlur=w*0.04;ctx.drawImage(im,o.x*CW-w/2,o.y*CH-h/2,w,h);ctx.restore();if(S.sel&&S.sel.kind==="overlay"&&S.sel.id===o.id){ctx.save();ctx.strokeStyle="#E0C488";ctx.lineWidth=2;ctx.setLineDash([6,5]);ctx.strokeRect(o.x*CW-w/2,o.y*CH-h/2,w,h);ctx.restore();}}continue;}
    ctx.save();const px=o.x*CW,py=o.y*CH,fs=o.size/100*CH*0.1+10;ctx.font=`${o.bold?"800":"600"} ${fs}px ${o.font},sans-serif`;ctx.textAlign="center";ctx.textBaseline="middle";const lines=(o.text||"").split("\n"),lh=fs*1.15;
    if(o.box){let mw=0;lines.forEach(ln=>{mw=Math.max(mw,ctx.measureText(ln).width);});const bw=mw+fs*0.8,bh=lh*lines.length+fs*0.4,bx=px-bw/2,by=py-bh/2,rr=fs*0.3;ctx.fillStyle=o.box;ctx.beginPath();ctx.moveTo(bx+rr,by);ctx.arcTo(bx+bw,by,bx+bw,by+bh,rr);ctx.arcTo(bx+bw,by+bh,bx,by+bh,rr);ctx.arcTo(bx,by+bh,bx,by,rr);ctx.arcTo(bx,by,bx+bw,by,rr);ctx.closePath();ctx.fill();}
    ctx.fillStyle=o.color;ctx.shadowColor="rgba(0,0,0,.45)";ctx.shadowBlur=o.box?0:fs*0.18;ctx.shadowOffsetY=o.box?0:fs*0.04;lines.forEach((ln,k)=>ctx.fillText(ln,px,py+(k-(lines.length-1)/2)*lh));ctx.restore();
    if(S.sel&&S.sel.kind==="overlay"&&S.sel.id===o.id){ctx.save();ctx.strokeStyle="#E0C488";ctx.lineWidth=2;ctx.setLineDash([6,5]);const w=CW*0.9;ctx.strokeRect(px-w/2,py-fs,w,fs*2*(o.text.split("\n").length));ctx.restore();}}}

/* ---- playback ---- */
let raf=null;function stopSources(){playingSources.forEach(s=>{try{s.stop()}catch(e){}});playingSources=[];}
function scheduleAudio(fromT){if(!AC)return;stopSources();const now=AC.currentTime;for(const c of S.audios){if(!c.buf)continue;const cd=c.out-c.in,endT=c.start+cd;if(endT<=fromT)continue;let offset=c.in,when=now+(c.start-fromT),dur=cd;if(c.start<fromT){offset=c.in+(fromT-c.start);when=now;dur=c.out-offset;}if(dur<=0)continue;const src=AC.createBufferSource();src.buffer=c.buf;const g=AC.createGain();g.gain.value=c.vol;src.connect(g);g.connect(master);try{src.start(Math.max(now,when),offset,dur);playingSources.push(src);}catch(e){}}}
function seekVideoForPlayhead(){if(!S.src)return;const loc=locate(S.playhead);if(loc)S.src.el.currentTime=loc.src;}
async function play(){if(!S.src||!S.segments.length||S.playing)return;ensureAudio();if(AC.state==="suspended")await AC.resume();if(S.playhead>=total()-0.02)S.playhead=0;S.playing=true;$("#playIco").innerHTML='<path d="M7 5h4v14H7zM13 5h4v14h-4z"/>';seekVideoForPlayhead();try{await S.src.el.play();}catch(e){}scheduleAudio(S.playhead);loop();}
function pause(){S.playing=false;$("#playIco").innerHTML='<path d="M8 5v14l11-7z"/>';if(S.src)S.src.el.pause();stopSources();if(raf)cancelAnimationFrame(raf);}
function loop(){if(!S.playing)return;const loc=locate(S.playhead);if(loc&&S.src){const seg=S.segments[loc.i];S.playhead=segStart(loc.i)+clamp(S.src.el.currentTime-seg.in,0,segDur(seg));if(S.src.el.currentTime>=seg.out-0.03||S.src.el.paused){const ns=loc.i+1;if(ns<S.segments.length){S.src.el.currentTime=S.segments[ns].in;S.playhead=segStart(ns)+0.001;if(S.src.el.paused)S.src.el.play().catch(()=>{});}else{S.playhead=total();pause();updatePlayhead();drawFrame();return;}}}drawFrame();updatePlayhead();raf=requestAnimationFrame(loop);}
function seekTo(t){S.playhead=clamp(t,0,total());if(S.src){const loc=locate(S.playhead);if(loc)S.src.el.currentTime=loc.src;}if(S.playing)scheduleAudio(S.playhead);updatePlayhead();if(!S.playing)drawFrame();}
$("#playBtn").addEventListener("click",()=>S.playing?pause():play());

/* ---- timeline ---- */
function updatePlayhead(){playheadEl.style.left=(S.playhead*S.pps)+"px";$("#timeLbl").textContent=fmt(S.playhead)+" / "+fmt(total());const tr=$("#tracks"),x=S.playhead*S.pps;if(x<tr.scrollLeft+40)tr.scrollLeft=x-40;else if(x>tr.scrollLeft+tr.clientWidth-40)tr.scrollLeft=x-tr.clientWidth+40;}
function renderRuler(){const T=Math.max(total(),1);tlinner.style.width=Math.max(T*S.pps+20,$("#tracks").clientWidth)+"px";ruler.innerHTML="";let step=1;if(S.pps<30)step=5;else if(S.pps<60)step=2;else if(S.pps>120)step=.5;for(let t=0;t<=T+0.001;t+=step){const d=document.createElement("div");d.className="tick";d.style.left=(t*S.pps)+"px";d.textContent=fmt(t).replace(/\.\d$/,"");ruler.appendChild(d);}}
function clipEl(cls,left,width,label,sel,data){const el=document.createElement("div");el.className="clip "+cls+(sel?" sel":"");el.style.left=left+"px";el.style.width=Math.max(width,10)+"px";el.innerHTML=`<div class="h l"></div><div class="cl-t">${esc(label)}</div><div class="h r"></div>`;Object.assign(el.dataset,data);return el;}
function renderTracks(){$$(".clip").forEach(c=>c.remove());const vt=$('[data-track="video"]'),at=$('[data-track="audio"]'),tt=$('[data-track="text"]');
  S.segments.forEach((s,i)=>vt.appendChild(clipEl("vid",segStart(i)*S.pps,segDur(s)*S.pps,"▦ "+fmt(segDur(s)),S.sel&&S.sel.kind==="segment"&&S.sel.id===s.id,{kind:"segment",id:s.id})));
  S.audios.forEach(a=>{const el=clipEl("aud",a.start*S.pps,(a.out-a.in)*S.pps,(a.missing?"⚠ ":"♪ ")+a.name,S.sel&&S.sel.kind==="audio"&&S.sel.id===a.id,{kind:"audio",id:a.id});if(a.missing)el.style.opacity=".6";at.appendChild(el);});
  S.overlays.forEach(o=>tt.appendChild(clipEl(o.kind==="image"?"img":"txt",o.start*S.pps,(o.end-o.start)*S.pps,o.kind==="image"?"🖼 grafica":(o.kind==="emoji"?o.text:"T "+(o.text||"").replace(/\n/g," ")),S.sel&&S.sel.kind==="overlay"&&S.sel.id===o.id,{kind:"overlay",id:o.id})));}
function renderAll(){renderRuler();renderTracks();updatePlayhead();refreshButtons();renderPanel();}
function refreshButtons(){$("#delBtn").disabled=!S.sel;$("#splitBtn").disabled=!S.src||!S.segments.length;}
function select(sel){S.sel=sel;renderTracks();refreshButtons();renderPanel();drawFrame();}
function getSelObj(){if(!S.sel)return null;if(S.sel.kind==="segment")return S.segments.find(s=>s.id===S.sel.id);if(S.sel.kind==="audio")return S.audios.find(a=>a.id===S.sel.id);if(S.sel.kind==="overlay")return S.overlays.find(o=>o.id===S.sel.id);}

/* ---- edits ---- */
function splitAtCore(t){const loc=locate(t);if(!loc)return false;const seg=S.segments[loc.i],srcT=loc.src;if(srcT<=seg.in+0.05||srcT>=seg.out-0.05)return false;const b=newSeg(srcT,seg.out);b.eff={...seg.eff};b.fx={...seg.fx};seg.out=srcT;seg.fo=0;b.fi=0;S.segments.splice(loc.i+1,0,b);return true;}
function splitAt(t){snapshot();if(splitAtCore(t)){renderAll();toast("Tagliato");}else S.undo.pop();}
async function beatSyncCuts(){if(!S.src){toast("Carica prima un video");return;}const clip=S.audios.find(a=>a.sfx&&MUSIC[a.sfx])||S.audios.find(a=>a.buf);if(!clip||!clip.buf){toast("Aggiungi prima una musica dalla banca");return;}
  toast("Cerco il ritmo…");const buf=clip.buf,ch=buf.getChannelData(0),sr=buf.sampleRate,win=Math.max(1,Math.floor(sr*0.02)),n=Math.floor(buf.length/win);const en=new Float32Array(n);let mx=1e-6;
  for(let i=0;i<n;i++){let s=0;const base=i*win;for(let j=0;j<win;j++){const v=ch[base+j]||0;s+=v*v;}en[i]=s;if(en[i]>mx)mx=en[i];}
  const beats=[];let last=-999;const minGap=Math.floor(0.45/(win/sr));
  for(let i=1;i<n;i++){const flux=en[i]-en[i-1];if(flux>mx*0.06&&en[i]>mx*0.16&&(i-last)>minGap){beats.push(i*win/sr+clip.start);last=i;}}
  if(beats.length<2){toast("Non trovo un ritmo chiaro in questa traccia");return;}
  snapshot();let cuts=0;beats.forEach(bt=>{if(bt>0.15&&bt<total()-0.15&&splitAtCore(bt))cuts++;});renderAll();toast(cuts+" tagli a tempo di musica");}
function delSel(){if(!S.sel)return;snapshot();if(S.sel.kind==="segment"){if(S.segments.length<=1){toast("Serve almeno un clip");S.undo.pop();return;}S.segments=S.segments.filter(s=>s.id!==S.sel.id);}else if(S.sel.kind==="audio")S.audios=S.audios.filter(a=>a.id!==S.sel.id);else if(S.sel.kind==="overlay")S.overlays=S.overlays.filter(o=>o.id!==S.sel.id);S.sel=null;S.playhead=clamp(S.playhead,0,total());renderAll();seekTo(S.playhead);toast("Eliminato");}
$("#splitBtn").addEventListener("click",()=>splitAt(S.playhead));$("#delBtn").addEventListener("click",delSel);$("#undoBtn").addEventListener("click",undo);

