$("#refFile").addEventListener("change",e=>{const f=e.target.files[0];if(!f)return;const v=document.createElement("video");v.src=URL.createObjectURL(f);v.muted=true;v.playsInline=true;v.addEventListener("loadeddata",()=>{try{v.currentTime=Math.min(0.5,v.duration/2);}catch(e){}});v.addEventListener("seeked",()=>{const c=document.createElement("canvas");c.width=120;c.height=213;const g=c.getContext("2d"),sc=Math.max(120/v.videoWidth,213/v.videoHeight),dw=v.videoWidth*sc,dh=v.videoHeight*sc;g.drawImage(v,(120-dw)/2,(213-dh)/2,dw,dh);S.refThumb=c.toDataURL("image/jpeg",0.6);c.toBlob(b=>{S.refBlob=b;renderPanel();},"image/jpeg",0.7);},{once:true});e.target.value="";});
