/* ---- AUDIO ---- */
function renderOffline(dur,build){const sr=44100,OAC=window.OfflineAudioContext||window.webkitOfflineAudioContext;const oc=new OAC(2,Math.ceil(sr*dur),sr);build(oc,dur);return oc.startRendering();}
function tone(oc,freq,t,dur,vol,type){const o=oc.createOscillator();o.type=type||"sine";o.frequency.value=freq;const g=oc.createGain();g.gain.setValueAtTime(0.0001,t);g.gain.linearRampToValueAtTime(vol,t+0.02);g.gain.exponentialRampToValueAtTime(0.0001,t+dur);o.connect(g);g.connect(oc.destination);o.start(t);o.stop(t+dur+0.05);}
const MUSIC={
 lofi:{name:"Lo-fi",d:"calmo",build:(oc,dur)=>{const ch=[[261.63,311.13,392],[233.08,277.18,349.23],[261.63,311.13,392],[196,246.94,311.13]];let t=0,i=0;while(t<dur){const c=ch[i%4];c.forEach(f=>tone(oc,f/2,t,1.9,0.1,"triangle"));tone(oc,c[0]/4,t,1.9,0.12,"sine");t+=2;i++;}}},
 allegro:{name:"Allegro",d:"vivace",build:(oc,dur)=>{const sc=[523.25,587.33,659.25,783.99,659.25,587.33];let t=0,i=0;while(t<dur){tone(oc,sc[i%sc.length],t,0.22,0.09,"triangle");if(i%4===0)tone(oc,261.63,t,0.5,0.08,"sine");t+=0.25;i++;}}},
 soft:{name:"Soft",d:"romantico",build:(oc,dur)=>{const arp=[392,493.88,587.33,493.88];let t=0,i=0;while(t<dur){tone(oc,arp[i%arp.length],t,0.6,0.1,"sine");if(i%4===0)tone(oc,196,t,1.6,0.09,"sine");t+=0.4;i++;}}},
 festivo:{name:"Festivo",d:"natalizio",build:(oc,dur)=>{const mel=[659.25,659.25,659.25,0,659.25,659.25,659.25,0,659.25,783.99,523.25,587.33,659.25,0];let t=0,i=0;while(t<dur){const f=mel[i%mel.length];if(f)tone(oc,f,t,0.28,0.09,"triangle");t+=0.3;i++;}}},
 cinema:{name:"Cinematic",d:"atmosfera",build:(oc,dur)=>{const ch=[[196,246.94,293.66],[174.61,220,261.63]];let t=0,i=0;while(t<dur){ch[i%2].forEach(f=>tone(oc,f,t,3.8,0.08,"sine"));t+=4;i++;}}},
 upbeat:{name:"Upbeat",d:"pop",build:(oc,dur)=>{const b=[523.25,0,659.25,0,587.33,0,783.99,0];let t=0,i=0;while(t<dur){const f=b[i%b.length];if(f)tone(oc,f,t,0.18,0.08,"square");if(i%2===0)tone(oc,130.81,t,0.2,0.1,"sine");t+=0.2;i++;}}}};
async function previewMusic(key){ensureAudio();if(AC.state==="suspended")await AC.resume();try{const buf=await renderOffline(4,MUSIC[key].build);const s=AC.createBufferSource();s.buffer=buf;const g=AC.createGain();g.gain.value=0.5;s.connect(g);g.connect(AC.destination);s.start();setTimeout(()=>{try{s.stop()}catch(e){}},4100);}catch(e){}}
async function addMusic(key){if(!S.src){toast("Carica prima un video");return;}ensureAudio();const dur=Math.min(Math.max(total(),6),60);try{const buf=await renderOffline(dur,MUSIC[key].build);snapshot();S.audios.push({id:uid(),name:MUSIC[key].name,buf,sfx:key,blob:null,assetId:null,start:0,in:0,out:buf.duration,vol:0.5,missing:false});renderTracks();select({kind:"audio",id:S.audios[S.audios.length-1].id});toast(MUSIC[key].name+" aggiunta");}catch(e){toast("Errore audio");}}
async function getSourceAudioBuffer(){if(S.src._abuf)return S.src._abuf;ensureAudio();let blob=S.src.blob;if(!blob){try{blob=await (await fetch(S.src.url)).blob();}catch(e){}}if(!blob)return null;try{const ab=await AC.decodeAudioData(await blob.arrayBuffer());S.src._abuf=ab;return ab;}catch(e){return null;}}
async function cutSilences(sens){if(!S.src){toast("Carica prima un video");return;}toast("Analizzo l'audio…");const ab=await getSourceAudioBuffer();if(!ab){toast("Nessun audio nel video");return;}
  const ch=ab.getChannelData(0),sr=ab.sampleRate,win=Math.max(1,Math.floor(sr*0.03)),n=Math.floor(ab.length/win);let peak=1e-6;const rms=new Float32Array(n);
  for(let i=0;i<n;i++){let s=0;const base=i*win;for(let j=0;j<win;j++){const v=ch[base+j]||0;s+=v*v;}const r=Math.sqrt(s/win);rms[i]=r;if(r>peak)peak=r;}
  const thr=peak*(0.03+(1-sens)*0.17),pad=0.08,minGap=0.18,minLen=0.3;let regions=[],start=null;
  for(let i=0;i<n;i++){if(rms[i]>=thr){if(start==null)start=i*win/sr;}else if(start!=null){regions.push([start,i*win/sr]);start=null;}}
  if(start!=null)regions.push([start,n*win/sr]);
  const merged=[];regions.forEach(r=>{r=[Math.max(0,r[0]-pad),Math.min(ab.duration,r[1]+pad)];if(merged.length&&r[0]-merged[merged.length-1][1]<minGap)merged[merged.length-1][1]=r[1];else merged.push(r);});
  const kept=merged.filter(r=>r[1]-r[0]>=minLen);
  if(!kept.length){toast("Tutto sotto soglia: abbassa la sensibilità");return;}
  snapshot();const preset=S.vibe?VIBES[S.vibe].grade.preset:"none",fx=S.vibe?{...VIBES[S.vibe].fx}:{};
  S.segments=kept.map(r=>({id:uid(),in:+r[0].toFixed(2),out:+Math.min(r[1],S.src.dur).toFixed(2),eff:{bri:100,con:100,sat:100,scale:100,preset},fx:{...fx},fi:0,fo:0}));
  S.sel=null;S.playhead=0;renderAll();seekTo(0);drawFrame();toast("Silenzi tagliati: "+kept.length+" clip · −"+(S.src.dur-total()).toFixed(1)+"s");}
/* my templates */
async function myTemplatesList(){if(CAP.db){try{const s=await CAP.db.collection("templates").orderBy("createdAt","desc").limit(50).get();return s.docs.map(d=>({id:d.id,...d.data()}));}catch(e){return[];}}return LS.get("verace_templates",[]);}
async function saveMyTemplate(name){const T=total()||1;const tpl={name,vibe:S.vibe,videoEnhance:S.videoFx.enhance,audioVoice:S.audioFx.voice,createdAt:Date.now(),overlays:S.overlays.filter(o=>o.kind==="text").map(o=>({text:o.text,x:o.x,y:o.y,size:o.size,color:o.color,font:o.font,bold:o.bold,box:o.box||null,a:+(o.start/T).toFixed(3),b:+(o.end/T).toFixed(3)})),sounds:S.audios.filter(a=>a.sfx).map(a=>({k:a.sfx,a:+(a.start/T).toFixed(3)}))};if(CAP.db&&CAP.canWrite){try{const r=await CAP.db.collection("templates").add(tpl);return r.id;}catch(e){}}tpl.id=uid();const arr=LS.get("verace_templates",[]);arr.unshift(tpl);LS.set("verace_templates",arr);return tpl.id;}
async function deleteMyTemplate(id){if(CAP.db&&CAP.canWrite){try{await CAP.db.collection("templates").doc(id).delete();return;}catch(e){}}LS.set("verace_templates",LS.get("verace_templates",[]).filter(t=>t.id!==id));}
async function applyMyTemplate(tpl){if(!S.src){toast("Carica prima un video");return;}snapshot();if(tpl.vibe)applyVibeCore(tpl.vibe);const T=total();S.overlays=S.overlays.filter(o=>o.kind==="image");(tpl.overlays||[]).forEach(o=>S.overlays.push({id:uid(),kind:"text",text:o.text,x:o.x,y:o.y,size:o.size,color:o.color,font:o.font,bold:o.bold,box:o.box||null,start:+(o.a*T).toFixed(2),end:+(o.b*T).toFixed(2)}));if(tpl.videoEnhance)S.videoFx.enhance=true;if(tpl.audioVoice){S.audioFx.voice=true;ensureAudio();setAudioFx();}if(tpl.sounds&&tpl.sounds.length){ensureAudio();for(const s of tpl.sounds){const gen=SFX[s.k]||MUSIC[s.k];if(!gen)continue;try{const d=gen.dur||Math.min(Math.max(T,6),60);const buf=await renderOffline(d,gen.build);S.audios.push({id:uid(),name:gen.name,buf,sfx:s.k,blob:null,assetId:null,start:+(s.a*T).toFixed(2),in:0,out:buf.duration,vol:gen.dur?0.85:0.5,missing:false});}catch(e){}}}if(tpl.vibe)S.vibe=tpl.vibe;S.sel=null;renderAll();drawFrame();toast("Modello «"+(tpl.name||"")+"» applicato");}
function noiseBuf(oc,dur){const sr=oc.sampleRate,n=Math.ceil(sr*dur),b=oc.createBuffer(1,n,sr),d=b.getChannelData(0);for(let i=0;i<n;i++)d[i]=Math.random()*2-1;return b;}
const SFX={whoosh:{name:"Whoosh",d:"transizione",dur:0.7,build:oc=>{const s=oc.createBufferSource();s.buffer=noiseBuf(oc,0.7);const f=oc.createBiquadFilter();f.type="bandpass";f.frequency.setValueAtTime(400,0);f.frequency.exponentialRampToValueAtTime(3600,0.5);f.Q.value=0.8;const g=oc.createGain();g.gain.setValueAtTime(0.0001,0);g.gain.linearRampToValueAtTime(0.5,0.18);g.gain.exponentialRampToValueAtTime(0.001,0.7);s.connect(f);f.connect(g);g.connect(oc.destination);s.start(0);}},
  pop:{name:"Pop",d:"accento",dur:0.2,build:oc=>{const o=oc.createOscillator();o.type="sine";o.frequency.setValueAtTime(900,0);o.frequency.exponentialRampToValueAtTime(180,0.12);const g=oc.createGain();g.gain.setValueAtTime(0.5,0);g.gain.exponentialRampToValueAtTime(0.001,0.18);o.connect(g);g.connect(oc.destination);o.start(0);o.stop(0.2);}},
  ding:{name:"Ding",d:"notifica",dur:0.8,build:oc=>{[1319,1760].forEach((fq,i)=>{const o=oc.createOscillator();o.type="sine";o.frequency.value=fq;const g=oc.createGain();g.gain.setValueAtTime(i?0.18:0.35,0);g.gain.exponentialRampToValueAtTime(0.001,0.8);o.connect(g);g.connect(oc.destination);o.start(0);o.stop(0.8);});}},
  riser:{name:"Riser",d:"tensione",dur:1.1,build:oc=>{const s=oc.createBufferSource();s.buffer=noiseBuf(oc,1.1);const f=oc.createBiquadFilter();f.type="highpass";f.frequency.setValueAtTime(300,0);f.frequency.exponentialRampToValueAtTime(5000,1.0);const g=oc.createGain();g.gain.setValueAtTime(0.05,0);g.gain.linearRampToValueAtTime(0.5,1.0);g.gain.exponentialRampToValueAtTime(0.001,1.1);s.connect(f);f.connect(g);g.connect(oc.destination);s.start(0);}},
  boom:{name:"Boom",d:"impatto",dur:0.9,build:oc=>{const o=oc.createOscillator();o.type="sine";o.frequency.setValueAtTime(120,0);o.frequency.exponentialRampToValueAtTime(45,0.5);const g=oc.createGain();g.gain.setValueAtTime(0.9,0);g.gain.exponentialRampToValueAtTime(0.001,0.9);o.connect(g);g.connect(oc.destination);o.start(0);o.stop(0.9);}},
  swoosh:{name:"Swoosh",d:"transizione",dur:0.5,build:oc=>{const s=oc.createBufferSource();s.buffer=noiseBuf(oc,0.5);const f=oc.createBiquadFilter();f.type="highpass";f.frequency.setValueAtTime(1500,0);f.frequency.exponentialRampToValueAtTime(600,0.4);const g=oc.createGain();g.gain.setValueAtTime(0.4,0);g.gain.exponentialRampToValueAtTime(0.001,0.5);s.connect(f);f.connect(g);g.connect(oc.destination);s.start(0);}},
  click:{name:"Click",d:"tap",dur:0.08,build:oc=>{const s=oc.createBufferSource();s.buffer=noiseBuf(oc,0.08);const g=oc.createGain();g.gain.setValueAtTime(0.5,0);g.gain.exponentialRampToValueAtTime(0.001,0.07);s.connect(g);g.connect(oc.destination);s.start(0);}},
  shimmer:{name:"Shimmer",d:"magia",dur:1.0,build:oc=>{[2093,2637,3136].forEach((fq,i)=>{const o=oc.createOscillator();o.type="triangle";o.frequency.value=fq;const g=oc.createGain();g.gain.setValueAtTime(0.0001,0);g.gain.linearRampToValueAtTime(0.14,0.1+i*0.08);g.gain.exponentialRampToValueAtTime(0.001,1.0);o.connect(g);g.connect(oc.destination);o.start(i*0.05);o.stop(1.0);});}},
  sparkle:{name:"Sparkle",d:"brillio",dur:0.7,build:oc=>{for(let k=0;k<6;k++){const o=oc.createOscillator();o.type="sine";o.frequency.value=1800+Math.random()*2200;const g=oc.createGain(),st=k*0.08;g.gain.setValueAtTime(0.0001,st);g.gain.linearRampToValueAtTime(0.18,st+0.01);g.gain.exponentialRampToValueAtTime(0.001,st+0.15);o.connect(g);g.connect(oc.destination);o.start(st);o.stop(st+0.16);}}},
  heartbeat:{name:"Battito",d:"ritmo",dur:0.9,build:oc=>{[0,0.28].forEach(st=>{const o=oc.createOscillator();o.type="sine";o.frequency.setValueAtTime(90,st);o.frequency.exponentialRampToValueAtTime(50,st+0.14);const g=oc.createGain();g.gain.setValueAtTime(0.0001,st);g.gain.linearRampToValueAtTime(0.8,st+0.02);g.gain.exponentialRampToValueAtTime(0.001,st+0.2);o.connect(g);g.connect(oc.destination);o.start(st);o.stop(st+0.25);});}}};
async function previewSfx(key){ensureAudio();if(AC.state==="suspended")await AC.resume();try{const buf=await renderOffline(SFX[key].dur,SFX[key].build);const s=AC.createBufferSource();s.buffer=buf;const g=AC.createGain();g.gain.value=0.9;s.connect(g);g.connect(AC.destination);s.start();}catch(e){}}
async function addSfx(key){if(!S.src){toast("Carica prima un video");return;}ensureAudio();try{const buf=await renderOffline(SFX[key].dur,SFX[key].build);snapshot();S.audios.push({id:uid(),name:SFX[key].name,buf,sfx:key,blob:null,assetId:null,start:S.playhead,in:0,out:buf.duration,vol:0.9,missing:false});renderTracks();select({kind:"audio",id:S.audios[S.audios.length-1].id});toast(SFX[key].name+" aggiunto");}catch(e){toast("Errore audio");}}
function renderAudio(){const p=$("#paneAudio");p.innerHTML="";const a=S.sel&&S.sel.kind==="audio"?getSelObj():null;
  if(a){const h=document.createElement("div");h.className="sec-t";h.textContent=(a.missing?"⚠ ":"")+a.name;p.appendChild(h);if(a.missing){const w=document.createElement("div");w.innerHTML=`<p class="hint" style="color:var(--danger)">File non salvato nel progetto. Ricaricalo.</p>`;const b=document.createElement("button");b.className="btn sm gold";b.textContent="Ricarica file";b.onclick=()=>{relinkTarget=a.id;$("#audioFile").click();};w.appendChild(b);p.appendChild(w);}p.appendChild(sliderEl("Volume",Math.round(a.vol*100),0,150,"%",v=>{a.vol=v/100;}));const r=document.createElement("div");r.className="row";const b=document.createElement("button");b.className="btn sm";b.textContent="Allinea al cursore";b.onclick=()=>{snapshot();a.start=S.playhead;renderTracks();};r.appendChild(b);p.appendChild(r);}
  const cs=document.createElement("div");cs.className="sec-t";cs.textContent="Tagli automatici";p.appendChild(cs);
  let sens=0.5;p.appendChild(sliderEl("Sensibilità (più alta = taglia di più)",50,10,90,"%",v=>{sens=v/100;}));
  const cbtn=document.createElement("button");cbtn.className="btn sm gold";cbtn.textContent="✂️ Taglia silenzi e voci basse";cbtn.onclick=()=>cutSilences(sens);p.appendChild(cbtn);
  const bbtn=document.createElement("button");bbtn.className="btn sm";bbtn.textContent="🎵 Tagli a tempo di musica";bbtn.onclick=beatSyncCuts;p.appendChild(bbtn);
  p.appendChild(Object.assign(document.createElement("p"),{className:"hint",textContent:"Silenzi: tiene solo il parlato. Tempo di musica: aggiunge tagli sul ritmo (prima aggiungi una musica). Annulla con Z."}));
  const st=document.createElement("div");st.className="sec-t";st.textContent="Migliora audio";p.appendChild(st);
  p.appendChild(switchEl("Enfatizza voce","Compressione + presenza del microfono",S.audioFx.voice,v=>{S.audioFx.voice=v;ensureAudio();setAudioFx();}));
  p.appendChild(switchEl("Riduci rumore","Taglia ronzii e rumore di fondo basso",S.audioFx.noise,v=>{S.audioFx.noise=v;ensureAudio();setAudioFx();}));
  p.appendChild(Object.assign(document.createElement("p"),{className:"hint",textContent:"Agisce sull'audio del video (microfono). La pulizia AI completa la faccio io nel render in alta qualità."}));
  const vt=document.createElement("div");vt.className="sec-t";vt.textContent="Voice over";p.appendChild(vt);
  const vo=document.createElement("div");vo.className="field";const ta=document.createElement("textarea");ta.id="voScript";ta.placeholder="Scrivi qui il testo del voice over…";ta.value=LS.get("verace_vo","");ta.oninput=()=>LS.set("verace_vo",ta.value);vo.appendChild(ta);p.appendChild(vo);
  const vr=document.createElement("div");vr.className="row";const vp=document.createElement("button");vp.className="btn sm";vp.textContent="🔊 Ascolta anteprima";vp.onclick=()=>previewVO(ta.value);const vu=document.createElement("label");vu.className="btn sm";vu.setAttribute("for","audioFile");vu.textContent="🎙 Carica la tua voce";vr.appendChild(vp);vr.appendChild(vu);p.appendChild(vr);
  p.appendChild(Object.assign(document.createElement("p"),{className:"hint",textContent:"Ascolti una voce di prova; per la voce AI definitiva nel video, incollami lo script in chat e la aggiungo nel render."}));
  const mt=document.createElement("div");mt.className="sec-t";mt.textContent="Musiche libere";p.appendChild(mt);
  p.appendChild(Object.assign(document.createElement("p"),{className:"hint",textContent:"Originali, senza copyright. Coprono tutto il reel."}));
  const ml=document.createElement("div");ml.className="soundlist";Object.entries(MUSIC).forEach(([k,v])=>{const row=document.createElement("div");row.className="srow";row.innerHTML=`<button class="iconbtn" title="Ascolta"><svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg></button><div class="nm"><b>${v.name}</b><span>${v.d}</span></div><button class="btn sm gold">Aggiungi</button>`;row.children[0].onclick=()=>previewMusic(k);row.children[2].onclick=()=>addMusic(k);ml.appendChild(row);});p.appendChild(ml);
  const ht=document.createElement("div");ht.className="sec-t";ht.textContent="Effetti sonori";p.appendChild(ht);
  const up=document.createElement("label");up.className="btn sm";up.setAttribute("for","audioFile");up.textContent="＋ Carica la tua musica";p.appendChild(up);
  const list=document.createElement("div");list.className="soundlist";Object.entries(SFX).forEach(([k,v])=>{const row=document.createElement("div");row.className="srow";row.innerHTML=`<button class="iconbtn" title="Ascolta"><svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg></button><div class="nm"><b>${v.name}</b><span>${v.d}</span></div><button class="btn sm gold">Aggiungi</button>`;row.children[0].onclick=()=>previewSfx(k);row.children[2].onclick=()=>addSfx(k);list.appendChild(row);});p.appendChild(list);}
async function previewVO(text){text=(text||"").trim();if(!text){toast("Scrivi prima il testo");return;}if(!CAP.tts){toast("L'anteprima voce è attiva nella versione online");return;}try{await CAP.tts.speak(text.slice(0,500));}catch(e){toast("Anteprima non disponibile");}}

